allow:
Bash(agent-browser open "https://www.theforktreeproject.com/journal/friends-of-forktree-planting-day-2025" && agent-browser wait --load networkidle && agent-browser eval --stdin <<'EVALEOF'
let title = document.querySelector\('.Blog-header h1, .BlogItem-title, article h1'\);
let body = document.querySelector\('.sqs-block-content p, article p, .Blog-content p'\);
let results = {};
if \(title\) {
  let s = window.getComputedStyle\(title\);
  results.title = {font: s.fontFamily, size: s.fontSize, weight: s.fontWeight, transform: s.textTransform, letterSpacing: s.letterSpacing, lineHeight: s.lineHeight};
}
if \(body\) {
  let s = window.getComputedStyle\(body\);
  results.body = {font: s.fontFamily, size: s.fontSize, weight: s.fontWeight, lineHeight: s.lineHeight};
}
JSON.stringify\(results\);
EVALEOF)
